/*
 * A287313  Primes that can be generated by the concatenation in base 9, in
 *          descending order, of two consecutive integers read in base 10.
 * https://oeis.org/A287313
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the nth prime obtained by concatenating * the base‑9
 *            representations of the consecutive integers * k+1 and k
 *            (descending order) for some integer k ≥ 1
 * Range:     u8 n <= 5, u16 n <= 25, u32 n <= 42, u64 n <= 42, u128 n <= 42,
 *            big any n
 * Helpers:   isPrimeGeneric
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include "../utils/isPrimeGeneric.h"

seq_t a(idx_t n) {
    if (n == 0) {
        return (seq_t)0;            /* defined only for n≥1, but safe guard */
    }

    idx_t count = 0;
    idx_t k = 1;                    /* start with k=1 */

    for (;;) {
        /* Compute power = 9^d_k, where d_k = number of base‑9 digits of k */
        seq_t power = (seq_t)1;
        idx_t t = k;
        while (t > 0) {
            power = power * (seq_t)9;
            t = t / (idx_t)9;
        }

        /* Candidate prime: concat(k+1, k) = (k+1)*9^d_k + k */
        seq_t candidate = ((seq_t)(k + 1)) * power + (seq_t)k;

        if (isPrimeGeneric(candidate)) {
            ++count;
            if (count == n) {
                return candidate;
            }
        }
        ++k;
    }
}
